            hertz = os.sysconf(os.sysconf_names['SC_CLK_TCK'])
            uptime = float(open('/proc/uptime').read().split()[0])
            start_time = uptime - (start_ticks / hertz)
            print('pid', pid, 'uptime_seconds', start_time)
    except Exception:
        pass
