import os, time
hertz = os.sysconf(os.sysconf_names['SC_CLK_TCK'])

def cpu(pid):
    stat = open(f'/proc/{pid}/stat').read().split()
    return (int(stat[13]) + int(stat[14])) / hertz

pids = []
for pid in os.listdir('/proc'):
    if pid.isdigit():
        try:
            cmd = open(f'/proc/{pid}/cmdline','rb').read().decode(errors='ignore')
            if 'dicke_wigner.py' in cmd:
                pids.append(int(pid))
        except Exception:
            pass

for pid in pids:
    try:
        c1 = cpu(pid)
        time.sleep(1)
        c2 = cpu(pid)
        print('pid', pid, 'cpu_delta_1s', c2 - c1)
    except Exception as e:
        print('pid', pid, 'err', e)
